UPDATE `product`
name = #{name}, description = #{description}, price = #{price}, stock = #{stock}, image = #{image}, images = #{images}, category_id = #{categoryId}, status = #{status}, is_hot = #{isHot}, is_new = #{isNew},
WHERE id = #{id}
